    86|function useCategoryChips(dealType: string | null | undefined): CategoryChip[] {
    87|  const t = (dealType ?? '').toLowerCase();
    88|  const tokenized: CategoryChip = {
    89|    id: 'tokenized',
    90|    label: 'Tokenized',
    91|    icon: <Hexagon size={13} color={Colors.primary} />,
