    94|  const jv: CategoryChip = {
    95|    id: 'jv',
    96|    label: 'JV Deal',
    97|    icon: <Users size={13} color={Colors.blue} />,
    98|    tint: Colors.blue,
    99|  };
   100|  const buyer: CategoryChip = {
   101|    id: 'buyer',
   102|    label: 'Buyer',
   103|    icon: <HomeIcon size={13} color={Colors.green} />,
   104|    tint: Colors.green,
   105|  };
   106|  switch (t) {
   107|    case 'jv':
