   122|const MAX_IMAGES = 8;
   123|const CAROUSEL_HEIGHT = 240;
   124|
   125|const InvestmentCard = memo(function InvestmentCard({
   126|  data,
   127|  onOpenDeal,
   128|  onInvest,
   129|  onLike,
   130|  onComment,
   131|  onSave,
   132|  onShare,
   133|  testIDPrefix = 'investment-card',
