   135|  const { width: screenWidth } = useWindowDimensions();
   136|  const cardWidth = Math.min(screenWidth - 32, 520);
   137|
   138|  const photos = useMemo(
   139|    () => (data.photos && data.photos.length > 0 ? data.photos.slice(0, MAX_IMAGES) : []),
   140|    [data.photos],
